package flow.study.domain.model;

/**
 * Row ids are String, not UUID.
 *
 * Every id in this app is a Postgres uuid, so UUID looks like the right type.
 * It is not, for one reason that outweighs the typing: these ids are
 * generated by Postgres, travel as JSON strings, go into H2 as text, and are
 * compared for equality and nothing else. Nothing in the product does uuid
 * arithmetic. UUID would mean parsing and re-serialising at every boundary
 * for no gain, and would turn a malformed id from a row that fails to push
 * into an exception while merely reading local data.
 */
public final class Ids {
    private Ids() {}

    /** Prefix for rows created offline, before the cloud has ever seen them. */
    public static final String LOCAL_PREFIX = "local-";

    /** True for ids a row carries before it has ever reached the cloud. */
    public static boolean isLocal(String id) {
        return id != null && id.startsWith(LOCAL_PREFIX);
    }
}
